const body = $input.first().json.body || $input.first().json;
// n8n puts the POST body under .body; fall back to the item itself when testing.

const aiFields = Array.isArray(body.aiFields) ? body.aiFields : [];
const company = body.company || {};
const products = Array.isArray(body.products) ? body.products : [];
const catalogue = Array.isArray(body.catalogue) ? body.catalogue : [];
const rep = body.rep || {};
if (aiFields.length === 0) throw new Error('aiFields must contain at least one field');
if (!company.name) throw new Error('company.name is required');

const slimProducts = products.map(function (p) {
  // Only the fields that describe the product (no terms, no diagram names).
  return { id: p.id, name: p.name, description: p.description, features: p.features };
});

const fieldSpec = aiFields.map(function (f) {
  const base = { key: f.key, label: f.label, type: f.type, instruction: f.hint || '' };
  if (f.type === 'table') base.row_keys = (f.columns || []).map(function (c) { return { key: c.key, label: c.label }; });
  return base;
});

const prompt = [
  'CUSTOMER COMPANY:', JSON.stringify(company, null, 2),
  '', 'SELECTED SLT PRODUCTS (' + slimProducts.length + '):', JSON.stringify(slimProducts, null, 2),
  '', 'PRODUCT CATALOGUE (ids you may use in recommendations):', JSON.stringify(catalogue),
  '', 'SALES REP (for tone only; do not mention by name):', JSON.stringify({ name: rep.name || '', designation: rep.designation || '' }),
  '', 'FIELDS TO FILL (return exactly one key per field key):', JSON.stringify(fieldSpec, null, 2)
].join('\n');

return [{ json: { prompt: prompt, aiFields: aiFields } }];

const aiFields = $('Build Prompt').first().json.aiFields || [];
// The field list the backend sent; only these keys are ever returned.

let raw = String($input.first().json.output || '').trim();
raw = raw.replace(/```json/gi, '').replace(/```/g, '').trim();

let parsed = null;
try {
  parsed = JSON.parse(raw);
} catch (e) {
  const start = raw.indexOf('{');
  const end = raw.lastIndexOf('}');
  if (start !== -1 && end > start) {
    try { parsed = JSON.parse(raw.substring(start, end + 1)); } catch (e2) { parsed = null; }
  }
}

if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) {
  return [{ json: { error: 'invalid_ai_output', raw: raw.substring(0, 2000) } }];
}

const text = function (v) {
  if (typeof v === 'string') return v;
  if (typeof v === 'number') return String(v);
  return '';
};
const cell = function (v) {
  return typeof v === 'boolean' ? v : text(v);
};

const values = {};
aiFields.forEach(function (f) {
  const v = parsed[f.key];
  if (f.type === 'table') {
    const rows = Array.isArray(v) ? v : [];
    values[f.key] = rows.filter(function (r) { return r && typeof r === 'object'; }).map(function (r) {
      const row = {};
      (f.columns || []).forEach(function (c) { row[c.key] = cell(r[c.key]); });
      return row;
    });
  } else {
    values[f.key] = text(v);
  }
});

return [{ json: { values: values } }];
